@spec editor_verbs_spec  src=tests/specs/editor_verbs_spec.lua  loc=265  sha=36fee5b  cases=11
@exercises swingEditor (se), configManager (h.cm), temperEditor (te)
@surface   se:open, se:libraryDescriptor, cm:getAt, cm:defaultFor, te:libraryDescriptor
@harness   mk

# Intent
  Verb descriptors on the swing/temper editors under the library model:
  `publish` lifts a project copy into the shared library, `revert` discards
  project drift back to its source, `tidy` (swing only) drops pristine
  unreferenced project copies, and `reloadFactory` re-imports the shipped
  catalogue (silent adds, a confirm per divergent copy). Instantiated over a harness cm/ds with a lib
  service; imgui stubbed via package.preload. Recipe lifted from
  temperEditor_tree_spec.

# Helpers
  @fn mkLib(h)  @ 20-25
  @fn facadeStub()  @ 29-38
      -- Swing reaches the arrange/tracker services only for the reference scan and
      -- default-slot resolution; a leaf on each covers the descriptor path.
  @fn mkModalHost(captured)  @ 42-47
      -- modalHost stub: no-op registerKind, plus capture the last openConfirm args so
      -- the confirm-gated publish path is observable.
  @fn mkSwing(h)  @ 49-60
  @fn mkTemper(h, inUse)  @ 62-74

# Cases
  @case 'swing onPublish lifts a project copy into the library tier'  [harness]  @ 78-90
  @case 'swing onPublish confirms before overwriting a divergent library copy'  [harness]  @ 93-112
  @case 'swing onReloadFactory imports absent names silently and confirms per divergent copy'  [harness]  @ 115-139
  @case 'temper onPublish lifts a fresh project copy without confirming'  [harness]  @ 142-154
  @case 'temper onPublish confirms before overwriting a divergent library copy'  [harness]  @ 157-176
  @case 'swing onRevert restores a divergent project copy from its source'  [harness]  @ 179-192
  @case 'swing descriptor flags a divergent project row as modified'  [harness]  @ 195-206
  @case 'temper descriptor flags a divergent project row as modified'  [harness]  @ 209-220
  @case 'swing and temper descriptors both expose onTidy'  [harness]  @ 223-231
  @case 'swing onTidy drops a pristine unreferenced copy, keeps a divergent one'  [harness]  @ 234-247
  @case 'temper onTidy drops a pristine unreferenced copy, keeps a divergent one'  [harness]  @ 250-263

